#include <omp.h>
#include <stdio.h>

#define ALIVE 'X'
#define DEAD '.'
#define LIVE_COUNT 8

char analyzeCell(char *c_m, int N, int i, int j) {
    char count = 0;
    int row_start = i > 0 ? i : 0;
    int row_end = i < N - 1 ? i : N - 1;
    int col_start = j > 0 ? j : 0;
    int col_end = j < N - 1 ? j : N - 1;

    for (int r = row_start; r <= row_end; r++) {
        for (int c = col_start; c <= col_end; c++) {
            if (r == i && c == j) continue;
            if (c_m[r * N + c] == ALIVE) count++;
        }
    }

    switch (count) {
        case 0:
        case 1:
        case 4:
        case 5:
        case 6:
        case 7:
            return DEAD;
        default:
            return ALIVE;
    }
}

